            ["bus"] = ("SURVEY FIELD LOG - DAY 2", new[] { "The minibus broke its axle a kilometre short. Radio dead. Dr. Lenko says the pulse is strongest here, in the old yard: one beat every eleven seconds, like a heart. We measured it for six hours. The needle never moved a degree.", "Day 3. Boris went to find the Cutting road and did not come back. The dogs - not dogs - circle the fence at night. Marta is crying and says she hears it too, in her teeth. We are staying in the bus.", "Day 5. Whoever finds this: the pulse is not from the ground. It comes from the north, and it is not a machine." }, "The Rusted Bus: a Surveyor field party measured a pulse in the Scrapyard and died waiting for rescue. It beat every eleven seconds, came from the north, and 'is not a machine'."),
            ["tally"] = ("WATCHER'S TALLY", new[] { "Crane cab, day 61. I keep the tally because no one else will. The Garrison drag people to the Loading Dock in bags. Day 19: four in. Day 33: nine in. Day 47: fourteen in.", "Three out, ever. They came up the hatch by themselves, at night, and walked south in a line, not speaking. I did not shoot. I should have.", "I am leaving the rifle and the tally. If you are the next watcher, count carefully." }, "The Crane Cab: a watcher counted the prisoners the Garrison took into the Loading Dock hatch - and the three who came out by themselves, walking south in a line, silent."),
            ["manifest"] = ("DISPOSAL MANIFEST 14", new[] { "Drums 1-40: solvent, routine. Drums 41-52: marked G, from the Institute lab at the Dock, sealed by hand. Do not open. Do not burn. Do not let the dogs near.", "(In pencil, below:) The dogs were already near." }, "The Chemical Dump: twelve drums marked G came from the Institute's lab under the Loading Dock, sealed by hand. Someone noted the dogs were already near."),
            ["transformer"] = ("TRANSFORMER LOG", new[] { "T4 hums on the beat again. Eleven seconds, exactly. I replaced the coil twice. The hum comes back. Reported to the Plant.", "The Plant says ignore the hum. The Plant stopped answering on the third day." }, "The Substation: transformer T4 hums on the same eleven-second beat. The Plant told the linemen to ignore it, then stopped answering."),
